@startuml

class Customer {
  + name : string
  + address : string
}

class Account {
  + balance : double
}

class SavingAccount extends Account {
  + interestRate : double
}

class InvestmentAccount extends Account {}

class Stock {
  + ticker : string
}

class StockOrder {
  + quantity : int
  + price : double
  + commission : double
}

Customer "1" -- "*" Account
InvestmentAccount "0..*" -- "*" Stock : buys
StockOrder --> "1" Stock
StockOrder --> "1" InvestmentAccount

@enduml

